package com.ianblk.zianmobs;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.effect.*;
import net.minecraft.world.item.*;
import net.minecraft.world.entity.player.Player;
import net.neoforged.neoforge.common.NeoForge;
import net.neoforged.neoforge.event.entity.player.CriticalHitEvent;
final class TitanSmoke {
 private static void check(boolean ok,String reason){if(!ok)throw new IllegalStateException(reason);}
 private static net.minecraft.world.entity.animal.Cow cow(ServerPlayer p){var c=EntityType.COW.create(p.serverLevel());c.moveTo(p.getX()+10,p.getY(),p.getZ()+10,0,0);c.setNoAi(true);p.serverLevel().addFreshEntity(c);return c;}
 private static void reset(ServerPlayer p){p.removeAllEffects();p.getPersistentData().getCompound(Player.PERSISTED_NBT_TAG).remove("ZianMobsCooldown_titan");}
 private static void hit(ServerPlayer p,net.minecraft.world.entity.animal.Cow c,boolean critical){c.invulnerableTime=0;NeoForge.EVENT_BUS.post(new CriticalHitEvent(p,c,1.5f,critical));c.hurt(p.damageSources().playerAttack(p),1);}
 static void run(ServerPlayer p){var main=p.getMainHandItem();var off=p.getOffhandItem();var data=p.getPersistentData().copy();var armorSlots=java.util.List.of(EquipmentSlot.HEAD,EquipmentSlot.CHEST,EquipmentSlot.LEGS,EquipmentSlot.FEET);var previousArmor=armorSlots.stream().map(p::getItemBySlot).toList();armorSlots.forEach(slot->p.setItemSlot(slot,ItemStack.EMPTY));var effects=p.getActiveEffects().stream().map(MobEffectInstance::new).toList();float hp=p.getHealth(),abs=p.getAbsorptionAmount();var sword=CompanionContent.EXTRAS.get(TitanAbilities.SWORD).get();var glove=CompanionContent.EXTRAS.get(TitanAbilities.GAUNTLET).get();var c=cow(p);c.getAttribute(Attributes.MAX_HEALTH).setBaseValue(200);c.setHealth(200);
 try{reset(p);p.setItemSlot(EquipmentSlot.MAINHAND,sword.getDefaultInstance());p.setItemSlot(EquipmentSlot.OFFHAND,ItemStack.EMPTY);hit(p,c,true);check(!TitanAbilities.awakened(p),"Sword alone triggered Titan buffs");p.setItemSlot(EquipmentSlot.MAINHAND,new ItemStack(Items.STICK));p.setItemSlot(EquipmentSlot.OFFHAND,glove.getDefaultInstance());hit(p,c,true);check(!TitanAbilities.awakened(p),"Gauntlet alone triggered buffs");p.setItemSlot(EquipmentSlot.MAINHAND,sword.getDefaultInstance());hit(p,c,false);check(!TitanAbilities.awakened(p),"Normal hit triggered Titan buffs");c.setInvulnerable(true);hit(p,c,true);check(!TitanAbilities.awakened(p),"Rejected critical triggered Titan buffs");c.setInvulnerable(false);hit(p,c,true);check(TitanAbilities.awakened(p),"Accepted paired critical did not activate buffs");for(var effect:java.util.List.of(MobEffects.REGENERATION,MobEffects.ABSORPTION,MobEffects.DAMAGE_RESISTANCE,MobEffects.FIRE_RESISTANCE,MobEffects.NIGHT_VISION,GearAbilities.TITAN_AWAKENING))check(p.getEffect(effect).getDuration()==600,"Titan buff duration is not 30 seconds");check(p.getEffect(MobEffects.REGENERATION).getAmplifier()==1&&p.getEffect(MobEffects.ABSORPTION).getAmplifier()==3,"Notch buff strength changed");long wait=p.getPersistentData().getCompound(Player.PERSISTED_NBT_TAG).getLong("ZianMobsCooldown_titan")-System.currentTimeMillis();check(wait>59000&&wait<=60000,"Titan cooldown is not 60 seconds");p.removeAllEffects();hit(p,c,true);check(!TitanAbilities.awakened(p),"Milk bypassed the Titan cooldown");var persisted=p.getPersistentData().copy();p.getPersistentData().merge(persisted);check(!GearAbilities.acquire(p,"titan",60),"Titan cooldown lost after data reload");reset(p);c.invulnerableTime=0;NeoForge.EVENT_BUS.post(new CriticalHitEvent(p,c,1.5f,false));c.hurt(p.damageSources().playerAttack(p),1000);check(TitanAbilities.awakened(p),"Real melee kill failed to activate the pair");
 reset(p);var distant=cow(p);try{var arrow=new net.minecraft.world.entity.projectile.Arrow(p.level(),p,new ItemStack(Items.ARROW),new ItemStack(Items.BOW));distant.hurt(p.damageSources().arrow(arrow,p),1000);check(!TitanAbilities.awakened(p),"Bow kill incorrectly triggered the sword pair");arrow.discard();}finally{distant.discard();}
 reset(p);var fullVictim=cow(p);fullVictim.getAttribute(Attributes.MAX_HEALTH).setBaseValue(200);fullVictim.setHealth(200);try{for(var slot:armorSlots){String id=switch(slot){case HEAD->"titan_helmet";case CHEST->"titan_chestplate";case LEGS->"titan_leggings";default->"titan_boots";};p.setItemSlot(slot,CompanionContent.ARMOR.get(id).get().getDefaultInstance());}hit(p,fullVictim,true);check(TitanAbilities.fullArmor(p)&&p.getEffect(GearAbilities.TITAN_AWAKENING).getDuration()==900&&p.getEffect(MobEffects.REGENERATION).getDuration()==900,"Full Titan set must grant 45 second buffs");long fullWait=p.getPersistentData().getCompound(Player.PERSISTED_NBT_TAG).getLong("ZianMobsCooldown_titan")-System.currentTimeMillis();check(fullWait>44000&&fullWait<=45000,"Full Titan set must wait 45 seconds");p.setItemSlot(EquipmentSlot.FEET,ItemStack.EMPTY);p.removeAllEffects();hit(p,fullVictim,true);check(!TitanAbilities.awakened(p),"Removing armor bypassed the existing cooldown");reset(p);hit(p,fullVictim,true);check(!TitanAbilities.fullArmor(p)&&p.getEffect(GearAbilities.TITAN_AWAKENING).getDuration()==600,"Incomplete armor wrongly grants the full-set bonus");}finally{fullVictim.discard();}
 var rescued=cow(p);rescued.setItemSlot(EquipmentSlot.OFFHAND,glove.getDefaultInstance());rescued.hurt(rescued.damageSources().generic(),1000);check(rescued.isAlive()&&rescued.getHealth()==1&&rescued.getOffhandItem().isEmpty(),"Gauntlet did not consume one item and rescue via native totem");check(rescued.hasEffect(MobEffects.REGENERATION)&&rescued.hasEffect(MobEffects.ABSORPTION)&&rescued.hasEffect(MobEffects.FIRE_RESISTANCE),"Gauntlet lost native totem effects");rescued.discard();
 var wrong=cow(p);wrong.setItemSlot(EquipmentSlot.MAINHAND,glove.getDefaultInstance());wrong.hurt(wrong.damageSources().generic(),1000);check(!wrong.isAlive()&&TitanAbilities.isGauntlet(wrong.getMainHandItem()),"Gauntlet protected from the wrong hand");wrong.discard();
 var bypass=cow(p);bypass.setItemSlot(EquipmentSlot.OFFHAND,glove.getDefaultInstance());bypass.hurt(bypass.damageSources().genericKill(),1000);check(!bypass.isAlive()&&TitanAbilities.isGauntlet(bypass.getOffhandItem()),"Gauntlet bypassed vanilla kill exceptions");bypass.discard();
 }finally{for(int i=0;i<armorSlots.size();i++)p.setItemSlot(armorSlots.get(i),previousArmor.get(i));c.discard();p.removeAllEffects();effects.forEach(p::addEffect);p.setHealth(hp);p.setAbsorptionAmount(abs);p.setItemSlot(EquipmentSlot.MAINHAND,main);p.setItemSlot(EquipmentSlot.OFFHAND,off);p.getPersistentData().remove(Player.PERSISTED_NBT_TAG);p.getPersistentData().merge(data);}}
 private TitanSmoke(){}
}
